import{_ as i,o as t,c as e,a2 as o}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"博客优化与供应链安全简介","description":"","frontmatter":{"title":"博客优化与供应链安全简介"},"headers":[],"relativePath":"site-setup/blog-optimization/index.md","filePath":"site-setup/blog-optimization/index.md","lastUpdated":1785388955000}'),l={name:"site-setup/blog-optimization/index.md"};function s(n,a,r,d,h,c){return t(),e("div",null,[...a[0]||(a[0]=[o(`<h1 id="博客优化与供应链安全简介" tabindex="-1">博客优化与供应链安全简介 <a class="header-anchor" href="#博客优化与供应链安全简介" aria-label="Permalink to &quot;博客优化与供应链安全简介&quot;">​</a></h1><h2 id="写在前面" tabindex="-1">写在前面 <a class="header-anchor" href="#写在前面" aria-label="Permalink to &quot;写在前面&quot;">​</a></h2><p>最近重构了一下这个博客的源码仓库，顺手把一些&quot;以前没认真想过&quot;的概念理了理。</p><p>这篇文章分两部分：</p><ul><li><strong>第一部分</strong>：记录这次重构过程中我觉得有用的几条&quot;博客优化方法&quot;，基本都是朴素实践</li><li><strong>第二部分</strong>：顺带整理一下&quot;供应链安全&quot;这个之前听过但没仔细想过的概念，结合本仓库的具体实践</li></ul><p>不是教程，只是备忘。</p><h2 id="第一部分-简单的博客优化方法" tabindex="-1">第一部分：简单的博客优化方法 <a class="header-anchor" href="#第一部分-简单的博客优化方法" aria-label="Permalink to &quot;第一部分：简单的博客优化方法&quot;">​</a></h2><h3 id="_1-让部署流程自动化" tabindex="-1">1. 让部署流程自动化 <a class="header-anchor" href="#_1-让部署流程自动化" aria-label="Permalink to &quot;1. 让部署流程自动化&quot;">​</a></h3><p>博客最常见的&quot;卡脖子点&quot;是构建→推送→上线的链路。手动跑命令容易出错、容易忘。</p><p>最朴素的自动化是写一个本地脚本串起所有步骤。更好一点的是把流程交给 CI：</p><ul><li>推送到 <code>main</code> 即触发构建</li><li>构建产物自动同步到发布仓库</li><li>全程不需要本地操作</li></ul><p>本博客的部署流程就属于这种——所有事情都在 <code>.github/workflows/deploy.yml</code> 里完成。</p><h3 id="_2-让日志可读" tabindex="-1">2. 让日志可读 <a class="header-anchor" href="#_2-让日志可读" aria-label="Permalink to &quot;2. 让日志可读&quot;">​</a></h3><p>如果自动化跑挂了，要能快速定位问题。这意味着：</p><ul><li>CI 步骤名称要清晰，不要全是 &quot;Run script 1&quot;</li><li>关键步骤之间加注释</li><li>出错时不要静默吞掉，CI 失败要让通知发出来</li></ul><h3 id="_3-让-修改清单-可追溯" tabindex="-1">3. 让&quot;修改清单&quot;可追溯 <a class="header-anchor" href="#_3-让-修改清单-可追溯" aria-label="Permalink to &quot;3. 让&quot;修改清单&quot;可追溯&quot;">​</a></h3><p>每次发布，应该能回答&quot;这次发了什么&quot;。最低成本的做法：</p><ul><li>commit message 写清楚改了什么</li><li>公开仓库的 commit 用统一前缀（如 <code>build:</code>）开头，log 才不会乱</li></ul><h3 id="_4-分离-源码-与-产物" tabindex="-1">4. 分离&quot;源码&quot;与&quot;产物&quot; <a class="header-anchor" href="#_4-分离-源码-与-产物" aria-label="Permalink to &quot;4. 分离&quot;源码&quot;与&quot;产物&quot;&quot;">​</a></h3><p>私有源码仓库 + 公开发布仓库这种分离方式有几个好处：</p><ul><li>源码可以公开也可以不公开（保护草稿、未发布内容）</li><li>发布仓库只放构建产物，体积小、下载快</li><li>公开仓库的 git log 只反映&quot;什么时候发了什么&quot;，不会泄露源码修改历史</li></ul><h3 id="_5-内部链接用绝对-url" tabindex="-1">5. 内部链接用绝对 URL <a class="header-anchor" href="#_5-内部链接用绝对-url" aria-label="Permalink to &quot;5. 内部链接用绝对 URL&quot;">​</a></h3><p>编译后产出的是 HTML，相对路径可能因找不到对应文件而失效。推荐用绝对 URL：</p><ul><li>所有&quot;返回主页&quot;链接：<code>https://blog.qinghelog.top/</code></li><li>所有指向子页面的链接：<code>https://blog.qinghelog.top/content/.../&lt;slug&gt;</code></li></ul><p>换域名时一次全量替换 <code>blog.qinghelog.top</code> 即可。</p><h3 id="_6-写-readme-给未来的自己" tabindex="-1">6. 写 README 给未来的自己 <a class="header-anchor" href="#_6-写-readme-给未来的自己" aria-label="Permalink to &quot;6. 写 README 给未来的自己&quot;">​</a></h3><p>文档写给&quot;半年后回来想改点什么的自己&quot;最有价值。内容包括：</p><ul><li>仓库结构图</li><li>日常操作（怎么加文章、怎么发版）</li><li>已知坑（&quot;不要在 Y 之前 commit X&quot;）</li></ul><h2 id="第二部分-供应链安全简介" tabindex="-1">第二部分：供应链安全简介 <a class="header-anchor" href="#第二部分-供应链安全简介" aria-label="Permalink to &quot;第二部分：供应链安全简介&quot;">​</a></h2><h3 id="什么是供应链攻击" tabindex="-1">什么是供应链攻击 <a class="header-anchor" href="#什么是供应链攻击" aria-label="Permalink to &quot;什么是供应链攻击&quot;">​</a></h3><p>软件供应链攻击指的是：攻击者不直接攻击你，而是攻击你<strong>依赖的东西</strong>——你用的库、你调用的 action、你下载的镜像、你引用的 CDN。</p><p>一旦被污染，你以为安全的代码实际上已经在执行恶意逻辑。</p><h3 id="常见的攻击面" tabindex="-1">常见的攻击面 <a class="header-anchor" href="#常见的攻击面" aria-label="Permalink to &quot;常见的攻击面&quot;">​</a></h3><p>对个人博客/小项目来说，主要供应链攻击面是这几类：</p><table tabindex="0"><thead><tr><th>攻击面</th><th>例子</th></tr></thead><tbody><tr><td>第三方 action</td><td>GitHub Actions 里 <code>uses: some-user/some-action@main</code></td></tr><tr><td>第三方库</td><td><code>package.json</code> 里的 <code>lodash</code> 被植入后门</td></tr><tr><td>构建工具</td><td>CI 里装的工具被替换</td></tr><tr><td>镜像/二进制</td><td><code>docker pull</code> 拉到被篡改的镜像</td></tr></tbody></table><h3 id="防御的核心思路" tabindex="-1">防御的核心思路 <a class="header-anchor" href="#防御的核心思路" aria-label="Permalink to &quot;防御的核心思路&quot;">​</a></h3><p>没有银弹，但有几个<strong>朴素且有效</strong>的原则：</p><ol><li><strong>锁版本</strong>：不要写 <code>@main</code> / <code>@latest</code>，写具体的 tag 或 commit SHA</li><li><strong>勤更新</strong>：定期 review 依赖的安全公告，但每次更新要可追溯</li><li><strong>最小权限</strong>：CI 不要给过宽的 token，能用 deploy key 就不用 PAT</li><li><strong>本地验证</strong>：重要依赖手动 review 一下 README、Star 数、Commit 历史</li><li><strong>出问题时能停</strong>：依赖要能快速替换或临时移除</li></ol><h3 id="本博客的实践" tabindex="-1">本博客的实践 <a class="header-anchor" href="#本博客的实践" aria-label="Permalink to &quot;本博客的实践&quot;">​</a></h3><p>回头看本博客的 <code>deploy.yml</code>，正好就是供应链安全原则的实战例子：</p><h4 id="_1-action-pin-到-commit-sha" tabindex="-1">1. Action pin 到 commit SHA <a class="header-anchor" href="#_1-action-pin-到-commit-sha" aria-label="Permalink to &quot;1. Action pin 到 commit SHA&quot;">​</a></h4><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">uses</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">actions/checkout@9c091bb21b7c1c1d1991bb908d89e4e9dddfe3e0</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 而不是 @v4 或 @main</span></span></code></pre></div><p><code>@main</code> 的风险是：action 维护者随时可以 push 改动，你的 workflow 行为当天就会变。pin 到 commit SHA 意味着：除非这个具体 commit 被改动（不可能，因为它已经存在），否则行为不会变。</p><p>代价是要定期手动更新 SHA（每 3-6 个月看一次）。</p><h4 id="_2-提交身份统一" tabindex="-1">2. 提交身份统一 <a class="header-anchor" href="#_2-提交身份统一" aria-label="Permalink to &quot;2. 提交身份统一&quot;">​</a></h4><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">user-email</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;qinghe-dev@outlook.com&quot;</span></span></code></pre></div><p>CI 推送 commit 时用的 email 跟本地保持一致，避免公开仓库出现&quot;两个作者&quot;的奇怪对比，也方便日后排查。</p><h4 id="_3-commit-message-加前缀" tabindex="-1">3. commit message 加前缀 <a class="header-anchor" href="#_3-commit-message-加前缀" aria-label="Permalink to &quot;3. commit message 加前缀&quot;">​</a></h4><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">commit-message</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  build: 同步博客构建产物</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  来源仓库: ...</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  源码 commit: ...</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  源码 message: ...</span></span></code></pre></div><p>公开仓库的 log 全是 <code>build:</code> 开头，干净统一；同时保留对源码 commit 的追溯链路。</p><h4 id="_4-files-目录的脱敏约定" tabindex="-1">4. files/ 目录的脱敏约定 <a class="header-anchor" href="#_4-files-目录的脱敏约定" aria-label="Permalink to &quot;4. files/ 目录的脱敏约定&quot;">​</a></h4><p>所有放进 <code>files/</code> 的代码片段都是<strong>对公网完全开放</strong>的。所以约定：</p><ul><li>没有真实凭据、token、SSH key</li><li>涉及个人/公司的字段用 <code>&lt;示例值&gt;</code>、<code>example.com</code> 等占位符</li><li>提交前按脱敏清单逐项检查</li></ul><h3 id="还想做但还没做的" tabindex="-1">还想做但还没做的 <a class="header-anchor" href="#还想做但还没做的" aria-label="Permalink to &quot;还想做但还没做的&quot;">​</a></h3><ul><li>加 <code>workflow_dispatch</code>（手动触发）和 <code>pull_request</code> 触发器（PR 时 dry-run），让 CI 反馈更及时</li><li>workflow 加 <code>actions/cache</code>，减少重复下载依赖</li><li>引入 Dependabot，自动监控依赖更新</li></ul><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li><a href="https://docs.github.com/en/actions/security-guides/security-hardening-for-github-actions" target="_blank" rel="noreferrer">GitHub 文档 - 安全加固你的 workflow</a></li><li><a href="https://docs.github.com/en/actions/security-guides/security-hardening-for-github-actions#using-third-party-actions" target="_blank" rel="noreferrer">GitHub 文档 - 使用第三方 action 的安全建议</a></li></ul>`,57)])])}const m=i(l,[["render",s]]);export{u as __pageData,m as default};
